head.script:
scwin.form_onLoadCompleted = function() {
    console.log("=== scwin.form_onLoadCompleted");
    alert("aaa");
};
scwin.onpageload = function() {
}

	scwin.setSimulate = function() {
		scwin.simulateWrapper('#wq_uuid_2_wq_uuid_3', 'key-combo', {
			combo: 'TAB'
		});
	}
	scwin.simulateWrapper = function(target, type, options) {
		WebSquare.wUnit.getJq(target).simulate(type, options);
	}
	scwin.setVal = function() {
		WebSquare.wUnit.getDomById('inputs').value = 'aaa'
	}	
	scwin.checkVal = function() {
		return WebSquare.wUnit.getDomById('inputs').value == 'aaa';
	}
	scwin.unitTest = function() {
		//Unit test
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "1000");
		//브라우저 프리즈체크용
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputs').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputs').focus()");
		WebSquare.wUnit.addCommand("pause", "500");

		WebSquare.wUnit.addCommand("set", "scwin.setVal()");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");

		//Run and Stop test
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
